arguments.command:
cd "$GITHUB_WORKSPACE" && python3 - <<'PY'
import subprocess
branches=["friend/rachel","friend/monica","friend/phoebe","friend/joey","friend/chandler","friend/ross"]
rows=[]
for b in branches:
    out=subprocess.check_output(["git","log","--format=%H|%ci|%s",f"origin/{b}"],text=True)
    for line in out.splitlines():
        sha,ci,subj=line.split("|",2)
        msg=subprocess.check_output(["git","show","-s","--format=%B",sha],text=True)
        if "Friend-Message: 1" in msg:
            # extract speaker/episode/reply
            speaker=episode=reply=""
            for l in msg.splitlines():
                if l.startswith("Speaker:"): speaker=l.split(":",1)[1].strip()
                if l.startswith("Episode:"): episode=l.split(":",1)[1].strip()
                if l.startswith("Reply-To:"): reply=l.split(":",1)[1].strip()
            # utterance after blank line following Reply-To? just print first 120 chars after
            body=msg.split("\n\n",2)
            text=body[-1].strip() if len(body)>1 else ""
            rows.append((ci,sha,b,speaker,episode,reply,text))
rows.sort(key=lambda r:(r[0],r[1]))
print("count",len(rows))
for r in rows[-40:]:
    print(r[0], r[1][:12], r[3], r[4], "reply="+r[5][:12], "|", r[6][:180].replace("\n"," "))
PY
